import math
import threading
from functools import wraps

def rate_limit(leak_rate, capacity, clock):
    rate = float(leak_rate)
    cap = float(capacity)
    if not math.isfinite(rate) or rate < 0:
        raise ValueError('leak_rate must be finite and non-negative')
    if not math.isfinite(cap) or cap < 0:
        raise ValueError('capacity must be finite and non-negative')

    def decorator(func):
        tokens = cap
        last_time = None
        lock = threading.Lock()

        @wraps(func)
        def wrapped(*args, **kwargs):
            nonlocal tokens, last_time
            with lock:
                now = float(clock())
                if last_time is None:
                    last_time = now
                else:
                    elapsed = now - last_time
                    if elapsed > 0:
                        tokens = min(cap, tokens + elapsed * rate)
                        last_time = now
                if tokens < 1.0:
                    return False
                tokens -= 1.0
            return func(*args, **kwargs)

        return wrapped

    return decorator
